import{z as A,x as B,o as E,c as d,q as i,j as s,D as r,d as n,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"字符串哈希","description":"","frontmatter":{"title":"字符串哈希","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/string-hashing.md","filePath":"cs/string-hashing.md","lastUpdated":1791413859000}'),p={name:"cs/string-hashing.md"};function D(h,a,m,C,f,b){const t=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=i('<h1 id="字符串哈希" tabindex="-1">字符串哈希 <a class="header-anchor" href="#字符串哈希" aria-label="Permalink to &quot;字符串哈希&quot;">​</a></h1><div class="epigraph"><p>把串看成 $b$ 进制整数模素数；子串哈希用前缀一次减一次乘，相等则以高概率当相等。</p><footer>—— 据 Karp and Rabin, Efficient Randomized Pattern-Matching Algorithms, IBM J. Res. Develop. 1987；Cormen, Leiserson, Rivest and Stein 第 32 章整理</footer></div><p><a href="/cs/palindromic-tree">上一课</a> 与 <a href="/cs/suffix-automaton">SAM</a>、<a href="/cs/suffix-array">SA</a> 都是确定性索引，空间或预处理不菲。只需比较若干子串是否相等时，滚动哈希期望 \\(O(1)\\)。<a href="/cs/prefix-sum-difference">前缀和</a> 的形状几乎相同。本课不建 fail。缺口是多项式哈希 / Karp–Rabin：前缀 \\(H[i]\\)，子串 \\([l,r)\\) 为 \\(H[r]-H[l]\\cdot b^{r-l}\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素比子串 \\(\\Theta(长度)\\)。哈希：选底 \\(b\\) 与模 \\(M\\)（或双模），碰撞概率约 \\(\\Theta(q^2/M)\\) 于 \\(q\\) 次比较（生日）。缺口不是通用散列族全文（后课），而是<strong>串上的滑动与前缀</strong>，使模式匹配、LCP 二分、去重期望变快。</p><p><span class="marginnote">多项式哈希翻译成白话：把字符串当成 b 进制数读出来再取模——「abc」被压成一个数字。比数字只需一次，比逐字符比字符串快；代价是不同串可能压成同一个数，那就是碰撞，概率由模数大小决定。</span></p><p><span class="marginnote">Karp–Rabin 1987。模 \\(2^{64}\\) 自然溢出不是素数域，对抗输入可打；教学合同写随机模或双质数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预处理 \\(H\\) 与幂 \\(p[i]=b^i\\)。比较：哈希相等再可选逐字符验证（确定性保险）。滚动：窗口右移减最左字符加最右。KMP 确定性线性；KR 期望线性、实现短。</p>',9)),(E(),s(o,null,{default:r(()=>[l(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E4%B8%B2%20S%22%5D%20--%3E%20H%5B%22%E5%89%8D%E7%BC%80%E5%93%88%E5%B8%8C%22%5D%0A%20%20H%20--%3E%20SUB%5B%22H%5Br%5D%20-%20H%5Bl%5D%20*%20b%5E%7Br-l%7D%22%5D%0A%20%20SUB%20--%3E%20EQ%5B%22%E7%9B%B8%E7%AD%89%3F%20%E9%AB%98%E6%A6%82%E7%8E%87%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与后缀数组：哈希可二分 LCP（每次中点比哈希），期望 \\(O(|P|\\log n)\\) 类，常数小；最坏碰撞要承认。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：取 b=131、M=1e9+7，串「abc」的哈希是 ((1×131 + 2)×131 + 3) mod M——每来一个字符做一次乘加。M 取大素数把碰撞概率压到约 q²/M；但代入 q=10 万、M=1e9+7，q²/M≈10^10/10^9≈10，碰撞几乎必然发生，单模已不保险——这正是合同写双质数的原因。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"必须固定一种下标与 \\(b^{len}\\)。溢出与负差要加 \\(M\\)。不要把哈希当加密；本课是数据结构加速。字母映射成 \\(1..|\\Sigma|\\)，避免前导零歧义。",-1)),a[7]||(a[7]=e("p",null,"下一课 Rope 处理的是可编辑大串，不是哈希；编辑会让前缀 \\(H\\) 失效，除非树节点存哈希——那是结合。",-1)),(E(),s(o,null,{default:r(()=>[l(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20W%5B%22%E5%BD%93%E5%89%8D%E7%AA%97%E5%8F%A3%E5%93%88%E5%B8%8C%20h%22%5D%20--%3E%20SUB%5B%22%E5%87%8F%E6%9C%80%E5%B7%A6%E5%AD%97%E7%AC%A6%EF%BC%9Ah%20%E5%87%8F%20s%5Bl%5D%20%E4%B9%98%20b%20%E7%9A%84%20len-1%20%E6%AC%A1%E6%96%B9%22%5D%0A%20%20SUB%20--%3E%20MUL%5B%22%E6%95%B4%E4%BD%93%E4%B9%98%E5%BA%95%EF%BC%9Ah%20%E4%B9%98%20b%22%5D%0A%20%20MUL%20--%3E%20ADD%5B%22%E5%8A%A0%E6%9C%80%E5%8F%B3%E5%AD%97%E7%AC%A6%EF%BC%9Ah%20%E5%8A%A0%20s%5Br%5D%22%5D%0A%20%20ADD%20--%3E%20MOD%5B%22%E5%8F%96%E6%A8%A1%EF%BC%9Ah%20%E5%AF%B9%20M%20%E5%8F%96%E4%BD%99%22%5D%0A%20%20MOD%20--%3E%20CMP%7B%22%E4%B8%8E%E6%A8%A1%E5%BC%8F%E5%93%88%E5%B8%8C%E7%9B%B8%E7%AD%89%EF%BC%9F%22%7D%0A%20%20CMP%20--%3E%7C%22%E7%9B%B8%E7%AD%89%22%7C%20VER%5B%22%E9%AB%98%E6%A6%82%E7%8E%87%E5%8C%B9%E9%85%8D%EF%BC%8C%E5%8F%AF%E8%A1%A5%E9%80%90%E5%AD%97%E7%AC%A6%E9%AA%8C%E8%AF%81%22%5D%0A%20%20CMP%20--%3E%7C%22%E4%B8%8D%E7%AD%89%22%7C%20SHIFT%5B%22%E7%AA%97%E5%8F%A3%E5%8F%B3%E7%A7%BB%E4%B8%80%E6%A0%BC%E9%87%8D%E6%9D%A5%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=i('<p><span class="marginnote">常见误区：把哈希相等当绝对相等。它只是高概率相等——写死不变的模数会被对抗输入构造卡掉，所以合同常用双模数或随机种子；要确定性答案，就在哈希相等后补一次逐字符验证。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明通用散列全部定理。完美散列给静态键集零碰撞，后单元。对抗哈希要用随机种子，合同写期望。</p><p>后课默认：静态子串相等可用哈希。可持久大串编辑用 Rope。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多项式哈希：前缀 \\(O(n)\\)，子串 \\(O(1)\\)，期望无碰撞。</li><li>模与底要随机化；可验证。</li><li>可编辑串结构是 Rope。</li><li>出处：Karp and Rabin, 1987；Cormen et al. 第 32 章。</li></ul>',6))])}const g=A(p,[["render",D]]);export{c as __pageData,g as default};
